def bf(planet1, planet2):
    planets_order = {
        "mercury": 1,
        "venus": 2,
        "earth": 3,
        "mars": 4,
        "jupiter": 5,
        "saturn": 6,
        "uranus": 7,
        "neptune": 8
    }

    planet1 = planet1.lower()
    planet2 = planet2.lower()

    if planet1 not in planets_order or planet2 not in planets_order:
        return ()

    order1 = planets_order[planet1]
    order2 = planets_order[planet2]

    if order1 == order2:
        return ()

    if order1 > order2:
        order1, order2 = order2, order1

    result = []
    for planet, order in planets_order.items():
        if order1 < order < order2:
            result.append(planet)

    return tuple(result)
